		assert.ok(
			parent,
			`Document should have an element matching "${parentSelector}"`,
		);
		const child = parent.querySelector(childSelector);
		assert.ok(
			child,
			`Element "${parentSelector}" should contain "${childSelector}"`,
		);
	},
